-- V11: households create each other through invites, and members join with a generated code (Phase 9, 2.0.0).

-- The join code is generated by the server: `join_id` (public, finds the household) plus a secret part whose
-- PBKDF2 hash is `code_hash`. Households from before 2.0 had a code their admin chose; it stops working, and
-- the admin generates a new one in the app. Until then nobody new can join.
ALTER TABLE household
    ALTER COLUMN code_hash DROP NOT NULL,
    ADD COLUMN join_id           TEXT UNIQUE,
    -- The household whose invite created this one (null: created with the server's setup code).
    ADD COLUMN invited_by        UUID REFERENCES household (id) ON DELETE SET NULL,
    -- Never deleted by the cleanup or the owner tool: the server owner's own household.
    ADD COLUMN protected         BOOLEAN NOT NULL DEFAULT FALSE,
    -- When the admin was warned that the household will be deleted for being unused.
    ADD COLUMN cleanup_warned_at TIMESTAMPTZ;

UPDATE household SET code_hash = NULL, protected = TRUE;

-- One-time invites an admin makes for a friend to create their own household. The code is long and random,
-- so it's stored as a SHA-256 hash (like device tokens) and looked up by it.
CREATE TABLE household_invite (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    household_id    UUID        NOT NULL REFERENCES household (id) ON DELETE CASCADE,
    code_hash       TEXT        NOT NULL UNIQUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,
    used_at         TIMESTAMPTZ,
    used_by         UUID        REFERENCES household (id) ON DELETE SET NULL,
    cancelled       BOOLEAN     NOT NULL DEFAULT FALSE
);

CREATE INDEX household_invite_household_idx ON household_invite (household_id);
